34	  workspace: StoredWorkspace | null,
35	  options: UseBoardDataOptions = {},
36	): UseBoardDataResult {
37	  const [features, setFeatures] = useState<ParsedFeature[]>([]);
38	  const [loading, setLoading] = useState<boolean>(workspace !== null);
39	  const [error, setError] = useState<BoardLoadError | null>(null);
40	  const [tick, setTick] = useState(0);
41	  const requestId = useRef(0);
42	
43	  const factory = options.clientFactory ?? defaultClientFactory;
44	
45	  const reload = useCallback(() => {
46	    setTick((t) => t + 1);
47	  }, []);
48	
49	  useEffect(() => {
50	    if (!workspace) {
51	      setFeatures([]);
52	      setLoading(false);
53	      setError(null);
54	      return;
55	    }
56	
57	    const id = ++requestId.current;
58	    let cancelled = false;
59	    setLoading(true);
60	    setError(null);
61	
62	    const client = factory(workspace);
63	    fetchBoardData(client)
64	      .then((data) => {
65	        if (cancelled || requestId.current !== id) return;
66	        setFeatures(data);
67	        setError(null);
68	        setLoading(false);
69	      })
70	      .catch((err: unknown) => {
71	        if (cancelled || requestId.current !== id) return;
72	        const boardError =
73	          err instanceof BoardLoadFailure ? err.error : mapClientError(err);
74	        setError(boardError);
75	        setLoading(false);
76	      });
77	
78	    return () => {
79	      cancelled = true;
80	    };
81	  }, [workspace, tick, factory]);
82	
83	  return { features, loading, error, reload };
84	}
