#!/usr/bin/env node
/**
 * Runner wrapper (D6c) — platform-owned entry point for every spawned executor.
 *
 * Exec's the executor binary, reads RESULT_PATH on exit, and POSTs
 * { handle, nonce, result } to $CALLBACK_URL with bounded exponential-backoff
 * retries on transport errors.
 *
 * Environment variables (required when invoked as main):
 *   BRIEFING_PATH — path to the briefing file passed through to the executor
 *   RESULT_PATH   — path the executor writes result.json to
 *   CALLBACK_URL  — broker HTTP endpoint to POST the completion to
 *   HANDLE        — opaque executor handle passed through to broker
 *   NONCE         — single-use token for broker authentication
 *   EXECUTOR_BIN  — path to the executor JS file
 *                   (default: /workflow/runtime/executors/claude/dist/index.js)
 *
 * All env vars (including BRIEFING_PATH and executor ABI vars) are inherited
 * by the executor subprocess unchanged.
 *
 * Node stdlib only; no node_modules required.
 */

import { spawn } from 'node:child_process';
import { readFileSync, existsSync } from 'node:fs';
import * as http from 'node:http';
import * as https from 'node:https';

const DEFAULT_EXECUTOR_BIN = '/workflow/runtime/executors/claude/dist/index.js';
const MAX_ATTEMPTS = 5;
const BASE_DELAY_MS = 500;
const MAX_STDERR_TAIL_LINES = 20;

/**
 * Spawn the executor and POST the result to the broker.
 *
 * All parameters default to the corresponding process env vars so the function
 * can be called with no arguments when running as the main entry point.
 */
export async function runWrapper({
  resultPath = process.env.RESULT_PATH ?? '',
  callbackUrl = process.env.CALLBACK_URL ?? '',
  handle = process.env.HANDLE ?? '',
  nonce = process.env.NONCE ?? '',
  executorBin = process.env.EXECUTOR_BIN ?? DEFAULT_EXECUTOR_BIN,
  maxAttempts = MAX_ATTEMPTS,
  baseDelayMs = BASE_DELAY_MS,
  env = process.env,
} = {}) {
  const stderrChunks = [];

  const child = spawn(process.execPath, [executorBin], {
    env,
    stdio: ['inherit', 'inherit', 'pipe'],
  });

  child.stderr.on('data', (chunk) => {
    process.stderr.write(chunk);
    stderrChunks.push(chunk.toString('utf8'));
  });

  const { code, signal, spawnError } = await new Promise((resolve) => {
    child.on('error', (err) => resolve({ code: null, signal: null, spawnError: err }));
    child.on('close', (exitCode, exitSignal) =>
      resolve({ code: exitCode, signal: exitSignal, spawnError: null }),
    );
  });

  let result;

  if (spawnError) {
    result = {
      terminal_status: 'failed',
      blocked_reason: `executor_spawn_error: ${spawnError.message}`,
    };
  } else if (code === 0 && existsSync(resultPath)) {
    try {
      result = JSON.parse(readFileSync(resultPath, 'utf8'));
    } catch (e) {
      result = {
        terminal_status: 'failed',
        blocked_reason: `result_parse_error: ${e.message}`,
      };
    }
  } else {
    const stderrFull = stderrChunks.join('');
    const stderrLines = stderrFull.split('\n').filter((l) => l.trim());
    const tail = stderrLines.slice(-MAX_STDERR_TAIL_LINES).join('\n').trim();

    const reason = signal
      ? `executor_killed_by_signal: ${signal}`
      : code !== null
        ? `executor_crashed (exit ${code})`
        : 'executor_no_result_file';

    result = {
      terminal_status: 'failed',
      blocked_reason: reason,
      ...(tail ? { blocked_suggestion: tail } : {}),
    };

